"use client";

import React from "react";
import {
  ExampleContent,
  TextParallaxContent,
} from "@/components/ui/src/TextParallaxContent";
import { AVATAR_LIST } from "@/fixture/avatars";
import Image from "next/image";

import Mission from "./Mission";

export default function Page() {
  /**
   * These are the avatar items
   */
  const AVATARS = AVATAR_LIST.map((member, index) => (
    <div
      key={index}
      className="flex flex-col items-center text-center px-4 py-6 rounded-4xl bg-white shadow-xl transition-transform duration-300 hover:scale-115 hover:bg-[#02438028]"
    >
      <Image
        src={member.img}
        alt={member.name}
        width={160}
        height={160}
        className="w-36 h-36 rounded-full object-cover mb-4 border-4 border-[#024380]"
      />
      <a
        href={member.link}
        target="_blank"
        rel="noopener noreferrer"
        className="text-lg font-medium text-neutral-800 hover:underline hover:underline-offset-2 transition-colors duration-200 break-words"
      >
        {member.name}
      </a>
    </div>
  ));

  return (
    <main className="w-full">
      <div className="bg-white">
        <TextParallaxContent
          imgUrl="/viksitbharat/Images/NewImages/00_TajMahal.jpg"
          subheading="Our vision for a progressive, prosperous & developed India, built
              on innovation, inclusivity, and development"
          heading="Viksit Bharat"
        >
          <ExampleContent />
        </TextParallaxContent>
        {/* Mission component */}
        <Mission />
        {/* A section on our goals for innovation */}
        <section
          id="About Us"
          className="w-full min-h-screen bg-[#005034] text-gray-900 flex items-center justify-center p-6"
        >
          <div className="container mx-auto grid grid-cols-12 gap-6">
            <div className="col-span-12 rounded-2xl p-6 bg-white shadow-lg flex items-center justify-center md:col-span-4">
              <Image
                src="/viksitbharat/Images/Mandala.jpg"
                width={800}
                height={800}
                alt="Technology"
                className="w-auto h-auto rounded-xl bg-gray-400"
              />
            </div>
            <div className="col-span-12 bg-gray-100 p-6 rounded-2xl shadow-lg md:col-span-8 grid grid-cols-1 divide-y ">
              {/* Row 1 */}
              <div className="grid grid-cols-12 gap-4 py-4 items-center justify-center place-items-center">
                <h1 className="text-3xl font-bold col-span-12 md:col-span-6">
                  AREAS OF FOCUS
                </h1>
                <p className="text-xl font-semi-bold text-center col-span-12 md:col-span-6">
                  To achieve self reliance in these sectors
                </p>
              </div>

              {/* Row 2 */}
              <div className="grid grid-cols-12 gap-4 py-4 place-items-center">
                <Image
                  src="/viksitbharat/Images/Processor.png"
                  width={800}
                  height={800}
                  alt="Sector 2"
                  className="w-24 h-auto rounded-lg col-span-12 md:col-span-6"
                />
                <div className="grid grid-col-1 gap1 text-center col-span-12 md:col-span-6">
                  <p className="text-xl font-bold">Power Electronics</p>
                  <p className="">
                    Envisioning advanced, sustainable power electronics
                    manufacturing for self-reliance.
                  </p>
                </div>
              </div>

              {/* Row 3 */}
              <div className="grid grid-cols-12 gap-4 py-4 place-items-center">
                <Image
                  src="/viksitbharat/Images/AICompute.png"
                  width={800}
                  height={800}
                  alt="Sector 2"
                  className="w-24 h-auto rounded-lg col-span-12 md:col-span-6"
                />
                <div className="grid grid-col-1 gap1 text-center col-span-12 md:col-span-6">
                  <p className="text-xl font-bold">Artificial Intelligence</p>
                  <p className="">
                    Safe data-driven innovation for efficiency, growth, and
                    self-reliance.
                  </p>
                </div>
              </div>
              <div className="grid grid-cols-12 gap-4 py-4 place-items-center">
                <Image
                  src="/viksitbharat/Images/Medicine.png"
                  width={800}
                  height={800}
                  alt="Sector 2"
                  className="w-24 h-auto rounded-lg col-span-12 md:col-span-6"
                />
                <div className="grid grid-col-1 gap1 text-center col-span-12 md:col-span-6">
                  <p className="text-xl font-bold">Medicine</p>
                  <p className="">
                    Pioneering medical advancements for a healthier,
                    self-sufficient future.
                  </p>
                </div>
              </div>
            </div>
          </div>
        </section>
        <section
          id="Contact Us"
          className="w-full min-h-screen bg-gray-100 text-gray-900 flex flex-col items-center justify-center p-6"
        >
          <div className="min-h-2/3 w-10/12 text-center">
            <h1 className="text-4xl mt-4 pt-6 pb-6 text-gray-900">OUR TEAM</h1>
            <p className="border-b-5 border-[#024380] text-xl pb-2">
              Our team consists of highly motivated individuals with years of
              experience in academia, entrepreneurship, and other ventures,
              dedicated to the development of the country.
            </p>
            <div className="grid grid-cols-1 md:grid-cols-5 gap-6 mt-6 pt-6 flex-wrap">
              {AVATARS}
            </div>
          </div>
        </section>
        {/*
      Second section Introduce ourselves 
      */}
        <section
          id="Mission"
          className="w-full min-h-screen bg-[#024380] text-white flex flex-col items-center justify-center p-6"
        >
          <div className="h-2/3 w-10/12 text-center">
            <h1 className="text-4xl mt-4 pt-6 pb-6 border-b-4 font-bold">
              OUR MISSION
            </h1>
            <div className="flex flex-col md:flex-row gap-6 mt-6 items-stretch">
              <div className="w-full md:w-1/3 text-xl flex flex-col items-center font-semibold">
                <p className="flex-1">
                  By bringing together India’s top inventors and entrepreneurs,
                  we aim to create world-leading enterprises.
                </p>
                <Image
                  src="/viksitbharat/Images/Innovation.png"
                  width={800}
                  height={800}
                  alt="Innovation"
                  className="mt-4 w-auto h-auto rounded-full bg-gray-200"
                />
              </div>
              <div className="w-full md:w-1/3 text-xl flex flex-col items-center font-semibold">
                <p className="flex-1">
                  We are committed to systematically indigenizing the underlying
                  technologies for long-term sustainability and growth.
                </p>
                <Image
                  src="/viksitbharat/Images/Technology.png"
                  width={800}
                  height={800}
                  alt="Technology"
                  className="mt-4 w-auto h-auto rounded-full bg-gray-400"
                />
              </div>
              <div className="w-full md:w-1/3 text-xl flex flex-col items-center font-semibold">
                <p className="flex-1">
                  Our mission is to drive innovation, foster economic
                  development, and make a global impact with cutting-edge
                  advancements.
                </p>
                <Image
                  src="/viksitbharat/Images/Globalization.png"
                  width={800}
                  height={800}
                  alt="Global Impact"
                  className="mt-4 w-auto h-auto rounded-full bg-gray-400"
                />
              </div>
            </div>
          </div>
        </section>
      </div>
    </main>
  );
}
